{"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕（约10000字，25%篇幅）：建立丧尸末世世界观，引入两位主角的身份设定，交代两人困在录音棚的现状，铺垫苏盏将摩斯密码误认为系统提示的核心误会",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "黑暗中的滴答声",
        "core_event": "失明的苏盏在废弃录音棚醒来，发现身边守着一个沉默不会说话的男人，耳机里传来规律的滴答声，用摩斯密码提示她如何躲避门口的丧尸",
        "emotional_tone": "紧张、茫然",
        "key_scenes": ["苏盏在黑暗中感知环境", "耳机里第一次出现摩斯密码滴答声", "陆沉站在门口挡住丧尸的剪影"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "生存系统指南",
        "core_event": "苏盏按照滴答声的提示行动，成功避开丧尸拿到了食物和水，她以为自己激活了末日生存系统，对身边沉默的狙击手放下戒心，两人达成无声的合作默契",
        "emotional_tone": "安定、微妙的信任感",
        "key_scenes": ["苏盏尝试翻译摩斯密码指令", "陆沉默默帮她挡开掉下来的货架", "两人第一次配合加固录音棚大门"]
      }
    ],
    "turning_point": "丧尸群第一次大规模围攻录音棚，两人按照\"系统提示\"合作播放提前录好的人声诱饵引开尸群，苏盏发现身边的男人和系统的指令配合得天衣无缝，对他产生强烈的依赖感"
  },
  "act_two": {
    "description": "第二幕（约20000字，50%篇幅）：冲突升级，两人的互动越来越多，双向暗恋的张力逐渐显现，陆沉重生者的线索和前世的伏笔慢慢浮出水面，苏盏开始对\"系统\"的真实性产生怀疑",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "诱饵计划",
        "core_event": "接下来的半个月里，两人多次合作播放人声诱饵引开周围的丧尸，苏盏负责调试录音设备，陆沉负责观察尸群动向，两人的配合越来越默契，苏盏偶尔触碰到陆沉的手，能摸到他喉咙处的旧伤疤",
        "emotional_tone": "酸甜、暧昧",
        "key_scenes": ["苏盏教陆沉怎么调节录音棚的音响参数", "陆沉把仅存的巧克力都留给苏盏", "苏盏摸到陆沉喉咙上的伤疤，问他是不是受伤了，陆沉只是点点头"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "熟悉的松木香",
        "core_event": "苏盏在陆沉身上闻到了熟悉的松木香，和三年前匿名给她送顶级录音设备的捐赠者身上的味道一模一样，她开始怀疑两人之前是不是见过，\"系统\"的提示也越来越有针对性，甚至知道她不吃香菜",
        "emotional_tone": "疑惑、心动",
        "key_scenes": ["苏盏靠在陆沉身边躲雨，闻到他身上的松木香", "系统提示苏盏吃罐头的时候挑没有香菜的那罐", "陆沉悄悄把苏盏掉在地上的发圈捡起来戴在自己手腕上"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "物资告急",
        "core_event": "录音棚的食物和水快用完了，陆沉每次出去找物资都能精准避开丧尸的行动路线，甚至能预判尸群的移动方向，苏盏觉得\"系统\"越来越神奇，同时也越来越好奇身边这个沉默的男人到底是什么来历",
        "emotional_tone": "焦虑、不安",
        "key_scenes": ["陆沉出去找物资，苏盏在录音棚里坐立不安等他回来", "陆沉受伤回来，苏盏摸索着给他包扎伤口", "系统提示三天后会有大规模尸群经过这里"]
      }
    ],
    "turning_point": "大规模尸群围攻录音棚，外墙被丧尸撞出裂缝，大门的锁也开始松动，两人意识到录音棚撑不了多久了，必须做出抉择"
  },
  "act_three": {
    "description": "第三幕（约10000字，25%篇幅）：高潮爆发，陆沉践行D21为亲人牺牲的核心冲突，真相揭开，核心误会消解，留下带余温的BE结局",
    "key_chapters": [
      {
        "chapter_number": 6,
        "chapter_title": "最后一夜",
        "core_event": "丧尸攻破大门的前一晚，陆沉用摩斯密码通过耳机告诉苏盏，明天早上会有救援赶到，让她待在录音棚里不要出去，不管听到什么声音都不要开门，他偷偷把提前录好告白的录音笔放在苏盏的口袋里",
        "emotional_tone": "压抑、悲伤",
        "key_scenes": ["陆沉最后一次给苏盏盖好毯子", "他用指尖轻轻碰了碰苏盏的脸颊，没敢让她发现", "陆沉把狙击枪装满子弹，靠在门后守了苏盏一夜"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "摩斯密码的真相",
        "core_event": "天刚亮，丧尸就攻破了大门，陆沉打开门冲了出去，开枪引走了所有尸群，苏盏听到外面的枪声想出去，耳机里的滴答声反复提示她不要动，等所有声音都消失后，她摸到口袋里的录音笔，播放后听到了陆沉的告白，才知道耳机里的从来不是什么系统，是他用摩斯密码敲出来的，他的失声是前世为了救她叫破喉咙导致的，他已经带着记忆重活了一次，就是为了救她",
        "emotional_tone": "崩溃、虐心",
        "key_scenes": ["陆沉开门引走尸群的脚步声和枪声", "苏盏播放录音笔听到陆沉的声音", "苏盏摸着耳机痛哭，才知道那些冷冰冰的系统提示，全是他藏了两辈子的深情"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "余声",
        "core_event": "救援按时赶到，苏盏活了下来，她带着陆沉的录音笔和狙击枪，每年都会回到这个录音棚，用他送她的录音设备，给他配自己写的故事，就好像他还在身边听一样",
        "emotional_tone": "遗憾、温暖的余韵",
        "key_scenes": ["救援人员在录音棚里找到苏盏", "一年后苏盏回到录音棚，给陆沉放自己配的故事", "最后一个镜头是录音笔里陆沉的声音：“苏盏，我爱你，从三年前第一次听你配音的时候就爱了”"]
      }
    ]
  }
}"}

