{"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕（约10000字，25%篇幅）：建立丧尸末世世界观，引入两位主角的身份设定，交代两人困在录音棚的现状，铺垫苏盏将摩斯密码误认为系统提示的核心误会",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "黑暗中的滴答声",
        "core_event": "失明的苏盏在废弃录音棚醒来，发现身边守着一个沉默不会说话的男人，耳机里传来规律的滴答声，用摩斯密码提示她如何躲避门口的丧尸",
        "emotional_tone": "紧张、茫然",
        "key_scenes": ["苏盏在黑暗中感知环境", "耳机里第一次出现摩斯密码滴答声", "陆沉站在门口挡住丧尸的剪影"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "生存系统指南",
        "core_event": "苏盏按照滴答声的提示行动，成功避开丧尸拿到了食物和水，她以为自己激活了末日生存系统，对身边沉默的狙击手放下戒心，两人达成无声的合作默契",
        "emotional_tone": "安定、微妙的信任感",
        "key_scenes": ["苏盏尝试翻译摩斯密码指令", "陆沉默默帮她挡开掉下来的货架", "两人第一次配合加固录音棚大门"]
      }
    ],
    "turning_point": "丧尸群第一次大规模围攻录音棚，两人按照\"系统提示\"合作播放提前录好的人声诱饵引开尸群，苏盏发现身边的男人和系统的指令配合得天衣无缝，对他产生强烈的依赖感"
  },
  "act_two": {
    "description": "第二幕（约20000字，50%篇幅）：冲突升级，两人的互动越来越多，双向暗恋的张力逐渐显现，陆沉重生者的线索和前世的伏笔慢慢浮出水面，苏盏开始对\"系统\"的真实性产生怀疑",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "诱饵计划",
        "core_event": "接下来的半个月里，两人多次合作播放人声诱饵引开周围的丧尸，苏盏负责调试录音设备，陆沉负责观察尸群动向，两人的配合越来越默契，苏盏偶尔触碰到陆沉的手，能摸到他喉咙处的旧伤疤",
        "emotional_tone": "酸甜、暧昧",
        "key_scenes": ["苏盏教陆沉怎么调节录音棚的音响参数", "陆沉把仅存的巧克力都留给苏盏", "苏盏摸到陆沉喉咙上的伤疤，问他是不是受伤了，陆沉只是点点头"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "熟悉的松木香",
        "core_event": "苏盏在陆沉身上闻到了熟悉的松木香，和三年前匿名给她送顶级录音设备的捐赠者身上的味道一模一样，她开始怀疑两人之前是不是见过，\"系统\"的提示也越来越有针对性，甚至知道她不吃香菜",
        "emotional_tone": "疑惑、心动",
        "key_scenes": ["苏盏靠在陆沉身边躲雨，闻到他身上的松木香", "系统提示苏盏吃罐头的时候挑没有香菜的那罐", "陆沉悄悄把苏盏掉在地上的发圈捡起来戴在自己手腕上"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "物资告急",
        "core_event": "录音棚的食物和水快用完了，陆沉每次出去找物资都能精准避开丧尸的行动路线，甚至能预判尸群的移动方向，苏盏觉得\"系统\"越来越神奇，同时也越来越好奇身边这个沉默的男人到底是什么来历",
        "emotional_tone": "焦虑、不安",
        "key_scenes": ["陆沉出去找物资，苏盏在录音棚里坐立不安等他回来", "陆沉受伤回来，苏盏摸索着给他包扎伤口", "系统提示三天后会有大规模尸群经过这里"]
      }
    ],
    "turning_point": "大规模尸群围攻录音棚，外墙被丧尸撞出裂缝，大门的锁也开始松动，两人意识到录音棚撑不了多久了，必须做出抉择"
  },
  "act_three": {
    "description": "第三幕（约10000字，25%篇幅）：高潮爆发，陆沉践行D21为亲人牺牲的核心冲突，真相揭开，核心误会消解，留下带余温的BE结局",
    "key_chapters": [
      {
        "chapter_number": 6,
        "chapter_title": "最后一夜",
        "core_event": "丧尸攻破大门的前一晚，陆沉用摩斯密码通过耳机告诉苏盏，明天早上会有救援赶到，让她待在录音棚里不要出去，不管听到什么声音都不要开门，他偷偷把提前录好告白的录音笔放在苏盏的口袋里",
        "emotional_tone": "压抑、悲伤",
        "key_scenes": ["陆沉最后一次给苏盏盖好毯子", "他用指尖轻轻碰了碰苏盏的脸颊，没敢让她发现", "陆沉把狙击枪装满子弹，靠在门后守了苏盏一夜"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "摩斯密码的真相",
        "core_event": "天刚亮，丧尸就攻破了大门，陆沉打开门冲了出去，开枪引走了所有尸群，苏盏听到外面的枪声想出去，耳机里的滴答声反复提示她不要动，等所有声音都消失后，她摸到口袋里的录音笔，播放后听到了陆沉的告白，才知道耳机里的从来不是什么系统，是他用摩斯密码敲出来的，他的失声是前世为了救她叫破喉咙导致的，他已经带着记忆重活了一次，就是为了救她",
        "emotional_tone": "崩溃、虐心",
        "key_scenes": ["陆沉开门引走尸群的脚步声和枪声", "苏盏播放录音笔听到陆沉的声音", "苏盏摸着耳机痛哭，才知道那些冷冰冰的系统提示，全是他藏了两辈子的深情"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "余声",
        "core_event": "救援按时赶到，苏盏活了下来，她带着陆沉的录音笔和狙击枪，每年都会回到这个录音棚，用他送她的录音设备，给他配自己写的故事，就好像他还在身边听一样",
        "emotional_tone": "遗憾、温暖的余韵",
        "key_scenes": ["救援人员在录音棚里找到苏盏", "一年后苏盏回到录音棚，给陆沉放自己配的故事", "最后一个镜头是录音笔里陆沉的声音：“苏盏，我爱你，从三年前第一次听你配音的时候就爱了”"]
      }
    ]
  }
}"}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
            "E24", "E25", "E26", "E27", "E28",
            "F29", "F30", "F31", "F32", "F33", "F34",
            "G35", "G36"
          ],
          "description": "普罗蒂36种剧情模式的标识符"
        },
        "x_axis_mode_name": {
          "type": "string",
          "description": "X轴模式的中文名称"
        },
        "y_axis_tags": {
          "type": "array",
          "description": "现代网文核心标签（表达载体）",
          "items": {
            "type": "string",
            "enum": [
              "双向暗恋",
              "系统流",
              "无限流",
              "种田流",
              "赛博朋克",
              "规则怪谈",
              "重生/穿越",
              "商战权谋",
              "克苏鲁",
              "第四天灾",
              "仙侠修真",
              "刑侦悬疑"
            ]
          },
          "minItems": 2,
          "maxItems": 3
        },
        "reaction_strength": {
          "type": "string",
          "enum": ["↗", "↘", "✷"],
          "description": "X轴与Y轴的化学反应强度符号"
        },
        "tension_stars": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5,
          "description": "故事张力指数（1-5星）"
        },
        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "x_axis_display": {
          "type": "string",
          "description": "X轴模式在故事中的具体显影方式"
        },
        "y_axis_combination_effect": {
          "type": "string",
          "description": "Y轴标签组合产生的效应描述"
        },
        "reaction_formula": {
          "type": "string",
          "description": "化学反应公式的一句话描述"
        },
        "platform_fit": {
          "type": "array",
          "description": "适合发布的平台类型",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "one_sentence_synopsis": {
      "type": "string",
      "description": "一句话故事梗概（30-50字）",
      "minLength": 30,
      "maxLength": 50
    }
  }
}

